text:
& .thread-card-dynamic-row {
  display: grid;
  grid-template:
    "subject subject" max-content
    "button info" minmax(auto, 1fr)
    / auto 1fr;
  gap: var(--thread-card-content-gap);
  align-items: center;
  padding: 0;
  margin: 0;
  line-height: 1.5;
  position: relative;
  isolation: isolate;
}
